static void closeTom(ux::Shell& shell,Canvas& canvas,ux::State expected){settle(shell,canvas);const auto fullBefore=canvas.full;CHECK(uitest::tom(shell,ib::tom::Close));shell.tick();canvas.changes();until([&]{shell.tick();canvas.changes();CHECK(!shell.failed());return !shell.tomPanel()->active()&&shell.state()==expected;});if(expected==ux::State::Picker){CHECK(canvas.full==fullBefore+1);std::vector<std::uint32_t> restored(underlay::Pixels,0xffffffffu);shell.compose({restored,1620,2160,1632},{0,0,1620,2160});CHECK(restored==canvas.pixels);}}
